TabBar::TabBar() { set_name("tabbar"); }
TabBar::~TabBar() = default;
SizeRequest TabBar::get_size_request() const { return {200,32,600,48}; }
void TabBar::draw(Painter& p) { if(!visible_)return; p.set_color(bg_); p.fill_rect(alloc_.x,alloc_.y,alloc_.width,alloc_.height); needs_redraw_=false; }
bool TabBar::on_event(Event& e) { if(e.type==EventType::MOUSE_DOWN){ emit("clicked");return true;} return Widget::on_event(e); }
